content:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Noto+Serif+JP:wght@300;400;600;700&family=Zen+Kaku+Gothic+New:wght@400;500;700&display=swap');

:root {
  --color-bg-primary: #fbf9f6;
  --color-bg-secondary: #f4ede4;
  --color-bg-tertiary: #ede3d7;
  --color-bg-dark: #221c19;
  --color-bg-card: #ffffff;

  --color-text-primary: #2d241e;
  --color-text-secondary: #6e5e54;
  --color-text-muted: #9c8b80;
  --color-text-light: #fbf9f6;

  --color-accent: #a3704c;
  --color-accent-hover: #885c3c;
  --color-accent-light: #d8b89d;
  --color-border: #e3d7cb;
  --color-border-subtle: #efe7de;

  --font-serif-ja: 'Noto Serif JP', 'Yu Mincho', serif;
  --font-serif-en: 'Cormorant Garamond', Georgia, serif;
  --font-sans: 'Zen Kaku Gothic New', 'Hiragino Kaku Gothic ProN', sans-serif;

  --shadow-sm: 0 2px 8px rgba(45, 36, 30, 0.05);
  --shadow-md: 0 6px 20px rgba(45, 36, 30, 0.08);
  --shadow-lg: 0 12px 36px rgba(45, 36, 30, 0.12);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-pill: 9999px;

  --transition-normal: all 0.3s ease;
  --transition-fast: all 0.2s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  color: var(--color-text-primary);
  background-color: var(--color-bg-primary);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  line-height: 1.75;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ------------------------------------
   App Layout
------------------------------------ */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* ------------------------------------
   Header & Nav
------------------------------------ */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(251, 249, 246, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-subtle);
  transition: var(--transition-normal);
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.2rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  gap: 2px;
}

.logo-title {
  font-family: var(--font-serif-en);
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-text-primary);
  line-height: 1;
}

.logo-sub {
  font-family: var(--font-serif-ja);
  font-size: 0.72rem;
  font-weight: 400;
  letter-spacing: 0.25em;
  color: var(--color-accent);
}

.nav {
  display: flex;
  align-items: center;
}

.nav-list {
  display: flex;
  list-style: none;
  gap: 2.5rem;
  align-items: center;
}

.nav-link {
  font-family: var(--font-serif-en);
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--color-text-secondary);
  position: relative;
  padding: 0.25rem 0;
  transition: var(--transition-fast);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1.5px;
  background-color: var(--color-accent);
  transition: width 0.3s ease;
}

.nav-link:hover {
  color: var(--color-accent);
}

.nav-link:hover::after {
  width: 100%;
}

/* ------------------------------------
   Hero Section
------------------------------------ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?q=80&w=2000&auto=format&fit=crop');
  background-size: cover;
  background-position: center 30%;
  color: var(--color-text-light);
  padding: 6rem 1.5rem;
  text-align: center;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(22, 17, 14, 0.45) 0%,
    rgba(22, 17, 14, 0.7) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.75rem;
}

.hero-tagline {
  font-family: var(--font-serif-en);
  font-size: 1.25rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-accent-light);
  font-weight: 400;
}

.hero-title {
  font-family: var(--font-serif-ja);
  font-size: clamp(2rem, 5vw, 3.6rem);
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: 0.14em;
  text-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

.hero-desc {
  font-family: var(--font-serif-ja);
  font-size: clamp(0.95rem, 2vw, 1.15rem);
  font-weight: 300;
  line-height: 2;
  letter-spacing: 0.08em;
  color: rgba(251, 249, 246, 0.9);
  max-width: 620px;
}

.hero-cta {
  margin-top: 1rem;
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* ------------------------------------
   Buttons
------------------------------------ */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background-color: var(--color-accent);
  color: #ffffff;
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  border-radius: var(--radius-sm);
  box-shadow: 0 4px 12px rgba(163, 112, 76, 0.3);
  transition: var(--transition-fast);
  border: 1px solid var(--color-accent);
}

.btn-primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(163, 112, 76, 0.4);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background-color: rgba(255, 255, 255, 0.08);
  color: var(--color-text-light);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(4px);
  transition: var(--transition-fast);
}

.btn-outline:hover {
  background-color: #ffffff;
  color: var(--color-text-primary);
  border-color: #ffffff;
  transform: translateY(-2px);
}

/* Light background variant for btn-outline */
.access-container .btn-outline {
  color: var(--color-accent);
  border-color: var(--color-accent);
  background: transparent;
}

.access-container .btn-outline:hover {
  background: var(--color-accent);
  color: #ffffff;
}

/* ------------------------------------
   Common Section Styles
------------------------------------ */
.section {
  padding: 6.5rem 1.5rem;
  position: relative;
}

.section:nth-of-type(even) {
  background-color: var(--color-bg-secondary);
}

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
}

.section-tag {
  font-family: var(--font-serif-en);
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.25em;
  color: var(--color-accent);
  text-transform: uppercase;
}

.section-title {
  font-family: var(--font-serif-ja);
  font-size: clamp(1.85rem, 3.5vw, 2.5rem);
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--color-text-primary);
  position: relative;
  padding-bottom: 1rem;
}

.section-title::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 45px;
  height: 2px;
  background-color: var(--color-accent);
}

.section-subtitle {
  font-family: var(--font-serif-ja);
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  letter-spacing: 0.05em;
  margin-top: 0.5rem;
  max-width: 580px;
}

/* ------------------------------------
   Concept Section
------------------------------------ */
.concept-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2.5rem;
  margin-top: 1rem;
}

.concept-card {
  background-color: var(--color-bg-card);
  padding: 3rem 2rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-subtle);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: var(--transition-normal);
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-border);
}

.concept-icon {
  font-size: 2.4rem;
  color: var(--color-accent);
  margin-bottom: 1.5rem;
  width: 72px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-border);
}

.concept-title {
  font-family: var(--font-serif-ja);
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--color-text-primary);
  margin-bottom: 1rem;
}

.concept-desc {
  font-size: 0.92rem;
  line-height: 1.9;
  color: var(--color-text-secondary);
}

/* ------------------------------------
   Menu Section
------------------------------------ */
.menu-tabs {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 3.5rem;
  flex-wrap: wrap;
}

.menu-tab-btn {
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-pill);
  font-family: var(--font-serif-en);
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--color-text-secondary);
  background-color: var(--color-bg-card);
  border: 1px solid var(--color-border);
  transition: var(--transition-fast);
}

.menu-tab-btn:hover {
  color: var(--color-accent);
  border-color: var(--color-accent);
  background-color: var(--color-bg-primary);
}

.menu-tab-btn-active {
  background-color: var(--color-accent);
  color: #ffffff !important;
  border-color: var(--color-accent);
  box-shadow: 0 4px 10px rgba(163, 112, 76, 0.25);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 2rem;
}

.menu-card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-subtle);
  display: flex;
  flex-direction: column;
  position: relative;
  transition: var(--transition-normal);
}

.menu-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.menu-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 10;
  background-color: var(--color-accent);
  color: #ffffff;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-pill);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.menu-image-wrap {
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  position: relative;
  background-color: var(--color-bg-secondary);
}

.menu-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.menu-card:hover .menu-image {
  transform: scale(1.06);
}

.menu-info {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.menu-name-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.25rem;
  gap: 0.5rem;
}

.menu-name {
  font-family: var(--font-serif-ja);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-text-primary);
  letter-spacing: 0.04em;
}

.menu-name-en {
  font-family: var(--font-serif-en);
  font-size: 0.88rem;
  color: var(--color-text-muted);
  font-style: italic;
  margin-bottom: 0.75rem;
}

.menu-price {
  font-family: var(--font-serif-en);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  white-space: nowrap;
}

.menu-desc {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-top: auto;
  padding-top: 0.5rem;
  border-top: 1px dashed var(--color-border-subtle);
}

/* ------------------------------------
   Access & Shop Info Section
------------------------------------ */
.access-container {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 3rem;
  align-items: stretch;
}

.access-info-col {
  background-color: var(--color-bg-card);
  padding: 2.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.access-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 2rem;
}

.access-row {
  border-bottom: 1px solid var(--color-border-subtle);
}

.access-row:last-child {
  border-bottom: none;
}

.access-label {
  padding: 1.1rem 1rem 1.1rem 0;
  font-family: var(--font-serif-ja);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--color-text-secondary);
  width: 25%;
  vertical-align: top;
}

.access-value {
  padding: 1.1rem 0;
  font-size: 0.95rem;
  color: var(--color-text-primary);
  vertical-align: top;
  line-height: 1.7;
}

.facility-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--color-border-subtle);
}

.facility-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.9rem;
  background-color: var(--color-bg-secondary);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 500;
  border: 1px solid var(--color-border);
}

/* Map Mock Card */
.map-col {
  display: flex;
  flex-direction: column;
}

.map-mock {
  height: 100%;
  min-height: 380px;
  background: #ede6dc url('https://images.unsplash.com/photo-1524661135-423995f22d0b?q=80&w=1200&auto=format&fit=crop') center/cover no-repeat;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 1.5rem;
}

.map-mock::before {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(247, 243, 237, 0.78);
  backdrop-filter: blur(1.5px);
}

.map-mock-header {
  position: relative;
  z-index: 2;
  background: rgba(255, 255, 255, 0.9);
  padding: 0.85rem 1.25rem;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--color-border-subtle);
  font-family: var(--font-serif-ja);
  font-size: 0.9rem;
  font-weight: 600;
}

.map-pin-box {
  position: relative;
  z-index: 2;
  align-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  margin: auto 0;
  background: #ffffff;
  padding: 1.25rem 2rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border);
}

.map-pin-icon {
  font-size: 1.8rem;
  color: var(--color-accent);
  margin-bottom: 0.4rem;
  animation: bounce 2s infinite ease-in-out;
}

@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

.map-pin-text {
  font-family: var(--font-serif-en);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: 0.05em;
}

.map-guide {
  position: relative;
  z-index: 2;
  background: rgba(255, 255, 255, 0.95);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  border: 1px solid var(--color-border-subtle);
  text-align: center;
}

/* ------------------------------------
   Footer
------------------------------------ */
.footer {
  background-color: var(--color-bg-dark);
  color: #c9bfb5;
  padding: 4.5rem 1.5rem 2.5rem;
  border-top: 1px solid #382e29;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.5rem;
  text-align: center;
}

.footer .logo-title {
  color: #fbf9f6;
}

.footer .logo-sub {
  color: var(--color-accent-light);
}

.footer-copy {
  font-family: var(--font-serif-en);
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  color: #8c7d73;
  padding-top: 2rem;
  border-top: 1px solid #332a24;
  width: 100%;
}

/* ------------------------------------
   Responsive Adjustments
------------------------------------ */
@media (max-width: 900px) {
  .access-container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

@media (max-width: 768px) {
  .header-container {
    padding: 1rem 1.25rem;
  }

  .nav-list {
    gap: 1.5rem;
  }

  .nav-link {
    font-size: 0.95rem;
  }

  .section {
    padding: 4.5rem 1.25rem;
  }

  .section-header {
    margin-bottom: 2.75rem;
  }

  .concept-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .concept-card {
    padding: 2.25rem 1.5rem;
  }

  .menu-grid {
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.5rem;
  }

  .access-info-col {
    padding: 1.75rem 1.25rem;
  }

  .access-label {
    width: 32%;
  }

  .map-mock {
    min-height: 320px;
  }
}

@media (max-width: 480px) {
  .header-container {
    flex-direction: column;
    gap: 0.75rem;
  }

  .hero {
    min-height: 75vh;
    padding: 4rem 1rem;
  }

  .hero-cta {
    width: 100%;
    flex-direction: column;
  }

  .hero-cta .btn-primary,
  .hero-cta .btn-outline {
    width: 100%;
  }

  .menu-tabs {
    gap: 0.5rem;
  }

  .menu-tab-btn {
    padding: 0.5rem 1rem;
    font-size: 0.95rem;
  }
}

export interface MenuItem {
  id: string;
  name: string;
  nameEn: string;
  category: 'coffee' | 'tea' | 'food' | 'dessert';
  price: number;
  description: string;
  isRecommended?: boolean;
  image: string;
}

export interface ShopInfo {
  name: string;
  address: string;
  station: string;
  tel: string;
  openHours: string;
  holiday: string;
  seats: string;
  hasWifi: boolean;
  hasPower: boolean;
}

export interface ConceptFeature {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  icon: string;
}

import { useState } from 'react';
import { MenuItem } from '../types';

interface MenuSectionProps {
  items?: MenuItem[];
}

type CategoryType = 'all' | 'coffee' | 'tea' | 'food' | 'dessert';

interface TabItem {
  id: CategoryType;
  label: string;
}

const CATEGORY_TABS: TabItem[] = [
  { id: 'all', label: 'All Items' },
  { id: 'coffee', label: 'Coffee' },
  { id: 'tea', label: 'Tea & Beverage' },
  { id: 'food', label: 'Light Meals' },
  { id: 'dessert', label: 'Sweets' },
];

const MenuSection = ({ items = [] }: MenuSectionProps) => {
  const [activeCategory, setActiveCategory] = useState<CategoryType>('all');

  const filteredItems = activeCategory === 'all'
    ? items
    : items.filter((item) => item.category === activeCategory);

  return (
    <section id="menu" className="section">
      <div className="section-inner">
        <header className="section-header">
          <span className="section-tag">Grand Menu</span>
          <h2 className="section-title">お品書き</h2>
          <p className="section-subtitle">
            厳選したシングルオリジン珈琲と、旬の食材を用いた自家製軽食・甘味をご用意しております。
          </p>
        </header>

        <div className="menu-tabs">
          {CATEGORY_TABS.map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={activeCategory === tab.id ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
              onClick={() => setActiveCategory(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="menu-grid">
          {filteredItems.map((item) => (
            <article key={item.id} className="menu-card">
              {item.isRecommended && (
                <span className="menu-badge">おすすめ</span>
              )}
              <div className="menu-image-wrap">
                <img
                  src={item.image}
                  alt={item.name}
                  className="menu-image"
                  loading="lazy"
                />
              </div>
              <div className="menu-info">
                <div className="menu-name-row">
                  <h3 className="menu-name">{item.name}</h3>
                  <span className="menu-price">¥{item.price.toLocaleString()}</span>
                </div>
                <div className="menu-name-en">{item.nameEn}</div>
                <p className="menu-desc">{item.description}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
};

